      "instructionsEn": "Complete these sentences with your own ideas (as in the last part of exercise 101.4 in the book): **Providing my neighbours don't object, ...**, **Supposing I get made redundant, ...**, **Unless the destruction of the world's rain forests is stopped, ...**. Then write one more sentence using **whether** (for example after **consider** or as **whether to**).",
      "ruleSummary": "Unless means 'if...not' in conditionals (You can't travel on this train unless you have a reservation) and takes a present tense for the future (Unless it rains, I'll pick you up, not Unless it will rain). In most real conditionals unless and if...not are both possible, but only if...not is used in most unreal conditionals (He would be happier if he didn't take things so seriously, not unless he took), when talking about emotions (I'll be amazed if Christie doesn't win), and in most questions (If you don't pass the test, what will you do?). Only unless introduces an afterthought (the course can't continue, unless you want the job, of course). If or whether both express two possibilities or uncertainty (I doubt whether/if anyone agrees); whether can be followed directly by or not (whether or not Tom was coming, not if or not). Whether is preferred after advise, consider, discuss; before to-infinitives (whether to buy apples or bananas); after prepositions; in a clause acting as subject or complement (Whether the minister will quit remains to be seen); and in noun + as to + whether (disagreement as to whether he was eligible). Other words introducing conditions: provided/providing (that), supposing (that), as/so long as. Judge whether each student sentence chooses the correct conjunction and tense for its meaning."
