      "instructions": "Hãy viết 3-4 'mẹo vặt trong nhà' (household hints) bằng tiếng Anh dùng **by + V-ing** (ví dụ: **By putting** a little salt in the water, you can...), như bài 102.4 trong sách. Sau đó viết thêm một câu với **on + V-ing** hoặc **without + V-ing**.",
      "instructionsEn": "Write 3-4 English 'household hints' using **by + -ing** (for example: **By putting** a little salt in the water, you can...), as in exercise 102.4 in the book. Then write one more sentence with **on + -ing** or **without + -ing**.",
      "ruleSummary": "Preposition + -ing clauses. After, before, besides, by, in, on, since, through, while, with and without can be followed by an -ing form, often to avoid repeating the subject (Since moving to London, we haven't had time to go to the theatre = Since we moved...); a passive form uses being + past participle (Before being changed last year, the speed limit was 70 kph; after being hit on the head). By + -ing gives the method or means (By working hard, she passed her exam); on + -ing means when (On returning from Beijing, he wrote to the embassy); in + -ing means as a result of (In criticising the painting, I knew I would offend her). By and in can overlap when the result comes from a chosen method, but only in is used when the result was not intended (In standing on the table, John banged his head, not By standing). With + subject + -ing gives a reason (With Louise living in Spain, we don't see her often); informal what with + -ing also gives a reason and needs no subject. Without + -ing says a second action doesn't happen (They left without paying), and can mean although or unless (Without seeing the pictures, I can't judge them). The implied subject of the -ing form must be the subject of the main clause. Judge whether each student sentence uses the right preposition for its meaning and a correct -ing or being + past participle form."
