              "kind": "text",
              "text": "**Even though** is a conjunction used to say that a fact doesn't make the rest of the sentence untrue. It connects ideas within a sentence:",
              "vi": "Even though là liên từ dùng để nói rằng một sự thật nào đó không làm cho phần còn lại của câu trở nên sai. Nó nối ý trong cùng một câu:"
