      "instructionsEn": "Write 4-5 English sentences about a trip or a memorable day of yours, using connectors between sentences (**as a result**, **nevertheless**, **even so**, **afterwards**) and connectors within a sentence (**while**, **even though**, **so that**). Add at least one sentence with **however** + adjective/adverb/**much**/**many**, for example: **However hard I tried**, I couldn't ...",
      "ruleSummary": "Connecting ideas. Adverbs and prepositional phrases used as adverbs connect a sentence to a previous one (As a result, Alternatively, Nevertheless, Even so, Consequently, In contrast, Meanwhile, At that time, Afterwards, After that, Then, Instead, Furthermore), while conjunctions and prepositions connect ideas within a single sentence (although, though, even though, while, whereas, yet, because, since, as, so, so that, in order to, when, whenever, after, before, as soon as). Between-sentence connectors can also join two clauses in one sentence after and, but, or, so, a semi-colon, colon or dash (You could fly via Singapore; however, this isn't the only way). Even though is a conjunction within a sentence (Even though much power has been lost, their influence...), while Even so starts a new sentence introducing a surprising fact (Much power has been lost. Even so, ...). However can connect ideas within a sentence when followed by an adjective, adverb or much/many (however necessary you think it is; however many times I hear it) or when it means 'no matter how' (However she held the mirror, she couldn't see...). Judge whether each connector suits the relationship between the ideas and whether it is used between or within sentences correctly, with correct punctuation."
