      "instructionsEn": "Write 4-5 English sentences describing where you live, work or study and how you travel every day, using **at**, **in** and **on** correctly: an address (**at** 12 ...), a road (**in**/**on** ... Road), the name of a company or school (**at** ...), and a means of transport (**on** the bus, **in** a taxi).",
      "ruleSummary": "At, in and on as prepositions of place. At is for a place seen as a point rather than an area and for events with a group of people (at New Street Station, at the far end of the room, at the conference, at Joan's party). On is for a position touching a flat surface or on something seen as a line such as a road or river (on the ceiling, on the wall/floor, on the Swan River). In is for a position within a larger area or space (in California, in her bag). Other uses: at Wembley Stadium (a point); in/at the pool; in Perth (within the city); stopped in/at Milan (at = points on a journey, in = stayed there); in/at Edinburgh (at = the festival/institution); in Los Angeles on business; at Manchester (the university); at Marks and Spencer (an organisation) but in a shoe shop (the kind of place); at the shop/bank/dentist's but in the bank to stress inside; on a farm but in a factory; in a taxi/car but on the bus/coach/plane/train (in to stress inside). At before an address (at 28 Lees Road), in or on before a road name (in/on Park Road), on for long roads (on the Pacific Highway), at for an institution named by its street (at Downing Street), on Wall Street for the financial institution, on the corner of the street but in the corner of the room. Judge whether each preposition of place is the natural choice and is well used."
