      "ruleSummary": "Prepositions of time at, in and on. AT: exact points of time (at midday, at 3 o'clock), short holiday periods (at Christmas, at Easter, at the weekend; US/Australian 'on the weekend'), short periods thought of as points (at the end of the month), mealtimes (at breakfast), night meaning 'when it is night' / 'each night' (at night), at the moment (= now). But: in the middle of May, in the night (a particular night), in a moment (= soon). IN: longer periods (in the winter, in May, in the 1990s, in the 16th century, in the days that followed), how long before something happens (in a few minutes), how long something takes (in a matter of weeks), parts of the day (in the morning, in the afternoon). ON: a particular day, date or part of a particular day (on Friday, on the 21st, on Easter Sunday, on Monday morning, on the morning of Friday 21st). No preposition before all, any, each, every, last, next, one, some, this, that + time expression (all morning, next Friday, every Saturday) or before (the day after) tomorrow / (the day before) yesterday. 'What time...?' is preferred to 'At what time...?'. Judge whether each student sentence uses the right preposition (or none) and is otherwise well formed."
