      "instructionsEn": "Write 3 New Year resolutions for yourself, ending with 'by the end of the year', 'until the end of January' and 'by the end of January'. Then add 2 sentences about your last holiday, one with **for** (how long) and one with **during** or **over** (when something happened).",
      "ruleSummary": "During, for, in, over, throughout; by and until. During or in: something happens within a period (during/in the last decade). During, not in: something happens at the same time as another event (during a maths test, during a visit to Madrid), or continues for the whole of a period (during (the whole of) its time in port); throughout has a similar meaning (throughout the winter). Over or during: an activity going on for a length of time within a period (over/during the past few days); but for a short event within a period we prefer during (she sneezed during the performance, not over). For says how long something continues (for a few minutes, for a couple of days); during says when it takes place (during a party, not for a party). By: something happens or is achieved before or at a time at the latest (be at the stadium by 2.30). Until: something continues up to a time (stay at the stadium until 2.30); in negatives until means 'not before' (don't open your presents until your birthday); till is informal. Judge whether each student sentence uses the right preposition and is otherwise well formed."
