      "instructionsEn": "Write 4 English sentences about your interests and experiences: one with **except (for)** (the only thing not included), one with **besides** or **apart from** (= as well as), one with **nothing but** or **nobody but**, and one with **But for...** saying what might have happened if something had not happened.",
      "ruleSummary": "Except (for), besides, apart from, but, but for. Except or except for introduce the only thing or person the main clause does not include (all meals except (for) lunch). Except for, not except, shows a general statement is not completely true (The car was undamaged, except for a broken headlight; Except for the weather, the holiday was perfect). Except, not except for, goes before prepositions, to-infinitives, bare infinitives and that-clauses (except in Scotland, except to do some shopping, nothing to do except keep an eye on him, except (that) they are made of plastic). Except (for) = with the exception of; besides = as well as / in addition to (Besides cricket, I enjoy football). Apart from can replace both. But means except after negative words like no, nobody, nothing (nothing but vague shadows). But for introduces a negative idea: what might have happened if something had not happened (But for his broken leg he would have been picked). In formal writing use but for for this, and except for for exceptions. Judge whether each student sentence uses the right word and is otherwise well formed."
