              "kind": "text",
              "text": "After some other verbs and nouns we can use either **about** or **on**. These include the verbs *advise*, *agree*, *decide*, *disagree*, *lecture*, *speak*, *speculate*, *talk*, *write*, and the nouns *advice*, *agreement*, *book/article/paper*, *consultation*, *decision*, *idea*, *information*, *lecture*, *opinion*, *question*:",
              "vi": "Sau một số động từ và danh từ khác, chúng ta có thể dùng about hoặc on. Chúng gồm các động từ advise, agree, decide, disagree, lecture, speak, speculate, talk, write, và các danh từ advice, agreement, book/article/paper, consultation, decision, idea, information, lecture, opinion, question:"
