      "instructionsEn": "Write 4-5 English sentences: describe a book or talk you recently read or heard (choose **about** or **on** to fit how formal it is), something you often worry or complain about (**worry about**, **complain about**), and how you do an everyday task, using **by** + -ing / by bus, by phone... and **with** + a tool.",
      "ruleSummary": "About and on; by and with. About and on both mean 'concerning'. About, not on, after argue, complain, find out, joke, know, protest, quarrel, read, teach, tell, worry, ask, enquire/inquire, learn, think, agree, hear, laugh, care, wonder and the nouns argument, chat, fuss, joke, letter, misunderstanding, quarrel. On, not about, after comment, concentrate, focus, insist, reflect. Either about or on after advise, agree, decide, disagree, lecture, speak, speculate, talk, write and the nouns advice, agreement, book/article/paper, consultation, decision, idea, information, lecture, opinion, question, when the speech or writing is formal or academic (She spoke on/about recent advances; a book on/about the history of Norway); about is preferred for informal speech or writing (I spoke about buying their car; a book about three men and their dog). By + noun or -ing = the action taken to do something (by braking hard); with + noun = what we use (open it with a screwdriver). Fixed phrases with by: by mistake, by accident, by phone, by bus/car, by air/road/rail/sea, by cheque/credit card, by heart, by hand, by post/fax/e-mail. With a determiner or a plural noun use another preposition (on the phone, in an email, in her new car, in buses). Judge whether each student sentence uses the right preposition and is otherwise well formed."
