      "instructionsEn": "Write 3-4 English sentences about learning and finding things out: something you recently found out (**I learnt about/of** ...), a time you asked after someone (**ask after**) or asked for something (**ask for**), and one of your plans (**I'm thinking of** + -ing) or your opinion of something (**what I think of** ...).",
      "ruleSummary": "Prepositions after the verbs learn, know, ask, enquire and think. Learn about/of and know about/of are both used for something that happens to somebody or a particular event (of is more formal): I have just learnt about/of the death of Dr Brown. Know + noun is for personal experience (My uncle knew Churchill), otherwise know about/of. Learn about and know about (not of) are used for a subject we study (learn about nutrition, knew little about black holes). Ask about / enquire (inquire) about means getting information about something or someone. Ask after / enquire after asks for information about a person, especially their health (ask/enquire about also possible). Ask for (not enquire for) is asking someone to give you something or do something. Enquire into (not ask into) means investigating an organisation, event or person. Think of is preferred for something that suddenly enters your mind, think about for considering something over a longer period and for concentrating on something. Think of is used to give or ask for opinions (What do you think of my car? I don't think a lot of his work), to talk about an idea, remembering (I can't think of where I put it), and intentions with (be) thinking of + -ing (I'm thinking of selling my motorbike). Judge whether each student sentence uses the correct preposition after the verb and is well formed."
