      "instructionsEn": "Write 3-4 English sentences about someone or something you care about: use **care about** or **care for**, one sentence with **don't care** + how/what/if, and one sentence with **shout at/to**, **point at/to** or **throw at/to**.",
      "ruleSummary": "Prepositions after the verbs care, shout, point, throw and wonder. Care about or care for: feeling affection for someone. Care about: being (not) concerned about something (He doesn't seem to care about the effect smoking has on him). Care for: looking after someone or something (= take care of); also formal 'like' in negatives (I don't care for the theatre much) and 'want' in offers (Would you care for a cup of coffee?). Care with no preposition before how, if, what, when, who (I don't care how much it costs). Shout at someone because you are angry; shout to someone far away so they can hear. Point something at = aim it (She pointed the knife at me); point at/to/towards = show where something is with a finger; point to = a fact suggests something else is true (House prices point to an upturn). Throw something to someone for them to catch; throw something at someone or something to try to hit them. Wonder about = think about doing something in the future or want to know about something (I've started to wonder about his health); wonder at = be surprised or impressed by something (literary). Also smile to yourself vs smile at someone, call at (visit) vs call to (say something to attract attention), look to someone for help vs look at, protest to someone vs protest at something. Judge whether each student sentence uses the correct preposition (or none) and is well formed."
