      "instructionsEn": "Write 3-4 English sentences describing a room, a street, or an unexpected event you once witnessed. Use **There is/There are/There was** to introduce new people or things (make the verb agree with the first noun), add one sentence with a relative clause or that-clause after the noun (**There's nobody who...**, **Is there any chance that...**), and try one formal sentence beginning **There being...**.",
      "ruleSummary": "There + be introduces a new person or thing, saying that it exists, happens or is found somewhere (There was a loud bang from upstairs, not A loud bang was from upstairs; Is there anybody in here?). Because it introduces topics, the noun after there + be is usually indefinite (a/an, some, any, no, nobody, something); with definite nouns (the, my, names) a normal subject is preferred (The cat was in the kitchen, rather than There was the cat in the kitchen), although there is the + noun can mark a change to a topic already known (And then there is the question of who is going to pay). The verb agrees with the noun (There is a good reason / There were too many people); informal speech sometimes uses there's before a plural; with a list the verb agrees with the first noun (there was a bottle of milk, some eggs and butter / there were some eggs, a bottle of milk and butter). There + be + noun can be followed by a that- or wh-clause (Is there a chance (that)...? There is no reason (why)...) or a relative clause; the relative pronoun is not normally left out before a finite verb (There was a small stream which/that ran..., or with a non-finite verb There was a small stream running...), though informal speech sometimes drops it. In formal English a clause with There being gives a reason (There being no evidence against him, Slade was released). Judge whether each student sentence uses there + be naturally, with correct agreement, suitable indefinite nouns, correct relative pronouns, and a correctly formed There being clause."
