      "titleEn": "Practice with AI",
      "instructions": "Hãy viết 3-4 câu tiếng Anh về những điều bạn thích, không thích hoặc đánh giá trong cuộc sống. Dùng it làm tân ngữ trước một mệnh đề (**I love it when...**, **I find it hard to...**, **I owe it to my family to...**), một câu với **it as** (**I see it as...**, **I regard it as...**), và một cụm **It's no...** hoặc **There's no...** (**There's no point in...**, **It's no wonder...**).",
      "instructionsEn": "Write 3-4 English sentences about things you like, dislike or judge in your life. Use it as an object before a clause (**I love it when...**, **I find it hard to...**, **I owe it to my family to...**), one sentence with **it as** (**I see it as...**, **I regard it as...**), and one **It's no...** or **There's no...** expression (**There's no point in...**, **It's no wonder...**).",
      "ruleSummary": "It can be the object of a verb, referring forward to a later clause. After liking verbs (enjoy, hate, like, love, don't mind, resent) it can be followed directly by a that-, wh- or if-clause (I hate it that you can swim so well; We like it when you stay), but many other verbs taking that- or wh-clauses do not use it this way (accept, discover, notice, predict, regret, remember: She discovered where she had put her ticket, not discovered it where). With believe, consider, find, feel, think, it is followed by a noun or adjective and then a that-, wh- or to-infinitive clause (they believe it unlikely that...; I thought it a waste of money to...). Leave and owe take it + to (somebody) + to-infinitive (Leave it to me to sort out; She owed it to her parents to do well). Accept, regard, see, take and view take it + as + noun/adjective + clause (We see it as an insult to...; I take it as encouraging when...). Fixed expressions: It's no secret/surprise/wonder/use/good, It was no coincidence, It's no longer; There's no alternative but to, no denying, no hope of, no need to, no point in, no question of, no reason to, no chance of, no doubt about. Judge whether each student sentence places it correctly (or correctly omits it), uses as where required, and uses these expressions with the right following form (-ing, to-infinitive, of/in + -ing, that-clause)."
