      "ruleSummary": "It-clauses (cleft sentences) focus attention on one piece of information: it + be + focused information + clause usually beginning with that (No, it was Tom that bought the car; It was two years ago that Helen bought it). Which or who can replace that, when and where are possible mainly in informal English, but how and why cannot (it was by improving distribution that he succeeded, not how he succeeded). What-clauses + be also focus information, which comes outside the what-clause (What we gave them was some home-made ice cream; What I'd like you to work on is exercise two), often to introduce a topic, explain, instruct or correct; the what-clause can come first or last (His rudeness was what upset me most). To emphasise an action use what + subject + do + be + (to) infinitive (What he did was (to) sell his flat). Other wh-words (how, when, where, who, why) are rarely used this way; instead use a noun phrase: The only reason (why/that)..., The place (where/that)..., The best way (in which/that)..., Somebody (who/that)..., The time (when/that)... (Somebody who I enjoy reading is Peter Carey, not Who I enjoy reading is). Judge whether each student sentence forms the cleft or what-clause correctly, uses a suitable connecting word, and places the focused information correctly."
