      "ruleSummary": "Inversion means putting the verb or an auxiliary before the subject. After a fronted adverbial phrase of direction or place, an intransitive verb can come before its subject, mainly in formal or literary style (In the doorway stood her father; Inside the first was a book of crosswords). With be this inversion is obligatory, and it is usual with verbs of place and movement such as climb, come, fly, go, hang, lie, run, sit, stand; it does not usually happen with other verbs, and never when the subject is a pronoun (not In an armchair sat she; round the corner it came). In speech, inversion follows here, there and adverbs like back, down, in, off, up, round (Here comes Sandra's car; up went the rocket). Conditional clauses can use inversion instead of if: Were the talks to fail, Should you need more information, Had Alex asked; this is more formal, and negatives are not contracted (Had he not resigned, not Hadn't he). In formal writing, inversion is preferred after as and than in comparisons (as was the coffee; than do their counterparts), but not with a pronoun subject (than we did, not than did we). Judge whether each sentence uses inversion correctly and naturally, with correct word order and verb forms."
