      "instructionsEn": "Write 4-5 formal English sentences with inversion, for example in a news report or an official notice: one beginning with a negative adverbial (**Never before...**, **Not until...**, **Under no circumstances...**), one with **Only when/Only after...**, and complete in your own way sentences beginning **Such was the...that...** and **So + adjective + was/did...that...** (for example: So nervous was he that...).",
      "ruleSummary": "In formal and literary English, a negative adverbial at the start of a clause causes subject-auxiliary inversion (do/does/did is added when there is no auxiliary): after never (before), rarely, seldom, barely/hardly/scarcely...when/before, no sooner...than (Seldom do we have goods returned; Hardly had I got onto the motorway when...); after only + a time expression (only after, only later, only once, only then, only when) and only + other prepositional phrases (Only by chance had Jameson discovered...; Only in this way was she able...); after preposition + no (at no time, in no way, on no account, under no circumstances); after not only, not until and not + object (Not a single word had she written); and after little with a negative meaning (Little did I realise). With only after/if/when or not until + a clause, the inversion is in the main clause (Only when the famine gets worse will governments act). So + adjective can be fronted for emphasis with inversion (So successful was her business that...; So dangerous did conditions become that...), and such + be emphasises degree (Such is the popularity of the play that...). Neither and nor starting a clause also take inversion (and neither could he see; nor did local residents). Contracted negatives are not used in inverted conditionals (Had we not taken, not Hadn't we). Judge whether each sentence uses inversion with correct word order, auxiliary and verb form."
